[
  {
    "id": "block-stamp-halfdrop",
    "name": "Half-Drop Stamp Press",
    "idea": "One small four-lobed stamp repeats in a half-drop grid across the upper part of an unbleached cotton field, and a slow diagonal wave presses each stamp down with a short deepening of ink that settles back over about twelve seconds.",
    "use": ["hero", "header", "empty-state"],
    "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
float bloom(vec2 q){float r=length(q);vec2 u=q/max(r,0.0001);float c4=1.0-8.0*u.x*u.x*u.y*u.y;return r-(0.17+0.05*c4);}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float S=9.0;
float px=S/u_resolution.y;
float aa=1.5*px;
vec2 g=p*S;
float cx=floor(g.x);
float sh=0.5*mod(cx,2.0);
g.y+=sh;
vec2 c=floor(g);
vec2 f=fract(g)-0.5;
vec2 cc=vec2(c.x+0.5,c.y+0.5-sh)/S;
float k=smoothstep(-0.08,0.24,cc.y+(h(c+7.0)-0.5)*0.08);
float kg=smoothstep(-0.08,0.24,p.y);
float w=fract(u_time/12.0-cc.x*0.35-cc.y*0.25-h(c)*0.04);
float pr=smoothstep(0.0,0.06,w)*(1.0-smoothstep(0.06,0.55,w));
vec2 j=(vec2(h(c+1.3),h(c+2.7))-0.5)*3.0*px;
vec2 q=(f-j)/(1.0+0.05*pr);
float fill=1.0-smoothstep(-aa,aa,bloom(q-vec2(1.5,-1.0)*px));
float line=1.0-smoothstep(-aa,aa,abs(bloom(q))-0.018);
float pip=1.0-smoothstep(-aa,aa,length(q+vec2(1.0,-1.0)*px)-0.045);
float gap=1.0-smoothstep(-aa,aa,length(vec2(f.x,abs(f.y)-0.5))-0.03);
float m=0.9+0.1*n(gl_FragCoord.xy*0.12+c*13.0);
float a=k*m*(0.82+0.18*pr);
vec3 col=u_c0*(0.985+0.03*n(gl_FragCoord.xy*0.6));
col=mix(col,u_c2,fill*a*0.85);
col=mix(col,u_c1,line*a);
col=mix(col,u_c3,pip*a);
col=mix(col,u_c3,gap*kg*0.6);
gl_FragColor=vec4(col,1.0);
}",
    "colors": ["#f3ecdc", "#2b2420", "#a8362a", "#c9962e"],
