  {
    "id": "block-layer-press-line",
    "name": "Layered Print Table",
    "idea": "A band of square-grid stamps slides slowly from right to left under three fixed press lines, so each stamp gains its outline, then its fill dots, then the gap dots, one color layer at a time, each layer a pixel off register.",
    "use": ["loading", "progress", "onboarding-slide"],
    "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float S=10.0;
float px=S/u_resolution.y;
float aa=1.5*px;
float ax=0.5*u_resolution.x/u_resolution.y;
float sp=0.25*u_time;
vec2 g=vec2(p.x*S+sp,p.y*S);
vec2 c=floor(g);
vec2 f=fract(g)-0.5;
float band=step(-2.5,c.y)*step(c.y,1.5);
vec3 L=vec3(0.55,0.2,-0.15)*ax;
vec3 d=L-(c.x+0.5-sp)/S;
vec3 on=smoothstep(0.0,0.02,d);
vec3 pr=on*(1.0-smoothstep(0.02,0.12,d));
vec2 q1=f-(vec2(h(c),h(c+1.7))-0.5)*2.0*px;
float dk=(abs(q1.x)+abs(q1.y))*0.7071-0.2;
float line=1.0-smoothstep(-aa,aa,abs(dk)-0.022);
vec2 q2=f-(vec2(h(c+3.1),h(c+4.3))-0.5)*2.0*px-vec2(1.0,-1.0)*px;
vec2 a2=abs(q2);
float dots=1.0-smoothstep(-aa,aa,length(vec2(max(a2.x,a2.y)-0.075,min(a2.x,a2.y)))-0.042);
vec2 gg=g+0.5;
vec2 cd=floor(gg);
vec2 fd=fract(gg)-0.5-vec2(-1.0,1.5)*px;
float bd=step(-1.5,cd.y)*step(cd.y,1.5);
float dg=smoothstep(0.0,0.02,L.z-(cd.x-sp)/S);
float gap=1.0-smoothstep(-aa,aa,length(fd)-0.035);
float m=0.88+0.12*n(gl_FragCoord.xy*0.13+c*11.0);
vec3 col=u_c0*(0.985+0.03*n(gl_FragCoord.xy*0.6));
col=mix(col,u_c1,line*band*on.x*m*(0.8+0.2*pr.x));
col=mix(col,u_c2,dots*band*on.y*m*(0.78+0.22*pr.y));
col=mix(col,u_c3,gap*bd*dg*m*0.85);
gl_FragColor=vec4(col,1.0);
}",
