  {
    "id": "block-border-band-drift",
    "name": "Printed Border Bands",
    "idea": "Narrow printed borders run along the top and bottom edges of a deep indigo field: a fine rule, a row of small lozenge stamps, a thinner rule and a row of dots, drifting slowly in opposite directions while a gentle pressure wave travels along the stamps and the center stays calm.",
    "use": ["paywall-plan", "card", "hero"],
    "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float px=1.0/u_resolution.y;
float aa=1.5*px;
float s=p.y<0.0?-1.0:1.0;
float e=0.5-abs(p.y);
float x=p.x+s*u_time*0.007;
float W=0.07;
float i=floor(x/W);
vec2 q=vec2(x-(i+0.5)*W,e-0.055);
q-=(vec2(h(vec2(i,s)),h(vec2(s,i+9.0)))-0.5)*2.0*px;
float pr=0.78+0.22*(0.5+0.5*sin(u_time*0.55-i*0.7));
float dl=((abs(q.x)*0.89+abs(q.y))-0.016)*0.75;
float outl=1.0-smoothstep(-aa,aa,abs(dl)-0.0022);
vec2 qa=q-vec2(1.0,-1.0)*px;
float df=((abs(qa.x)*0.89+abs(qa.y))-0.009)*0.75;
float fill=1.0-smoothstep(-aa,aa,df);
float xg=x-floor(x/W+0.5)*W;
float gd=1.0-smoothstep(-aa,aa,length(vec2(xg,e-0.055))-0.003);
float r1=1.0-smoothstep(-aa,aa,abs(e-0.024)-0.0022);
float r2=1.0-smoothstep(-aa,aa,abs(e-0.088)-0.0011);
float xd=x-(floor(x/(0.5*W))+0.5)*0.5*W;
float ds=1.0-smoothstep(-aa,aa,length(vec2(xd,e-0.108))-0.0032);
vec2 gq=mod(p+0.025,0.05)-0.025;
float fd=1.0-smoothstep(-aa,aa,length(gq)-0.0026);
float fz=smoothstep(0.125,0.145,e)*(1.0-smoothstep(0.15,0.32,e));
float m=0.9+0.1*n(gl_FragCoord.xy*0.14);
vec3 col=u_c0*(0.985+0.03*n(gl_FragCoord.xy*0.6));
col=mix(col,u_c1,r1*0.85*m);
col=mix(col,u_c3,r2*0.8*m);
col=mix(col,u_c2,fill*pr*m);
col=mix(col,u_c1,outl*pr*0.9*m);
col=mix(col,u_c1,gd*0.7*m);
col=mix(col,u_c3,ds*0.75*m);
col=mix(col,u_c3,fd*fz*0.3);
gl_FragColor=vec4(col,1.0);
}",
