float a=u_resolution.x/u_resolution.y;
float wide=smoothstep(0.8,1.2,a);
float R=min(0.32,0.42*a);
vec2 c=vec2(max(0.0,(a-0.5)*0.38),0.17*(1.0-wide));
vec3 col=u_c0;
vec2 g=p*4.5+vec2(0.5);
