vec3 bc=mix(u_c3,u_c2,step(0.65,rn));
float far=smoothstep(R*1.05,R*1.9,length(p-c));
col=mix(col,bc,bg*0.16*far);
vec2 q=p-c;
float d=length(q);
float ang=atan(q.y,q.x);
float arm=u_time*0.4488;
float del=mod(arm-ang,6.2832);
float tr=exp(-del*0.8);
vec3 fc=mix(mix(u_c3,u_c2,0.45),u_c2,tr*0.8);
float m=1.0-smoothstep(R-px,R+px,d);
col=mix(col,fc,m);
float rd=abs(fract(d*64.0)-0.5)/64.0;
float row=1.0-smoothstep(0.0012,0.0012+px,rd);
col=mix(col,u_c1,row*0.08*m);
vec2 dir=vec2(cos(arm),sin(arm));
float t=clamp(dot(q,dir),0.0,R);
float ad=length(q-dir*t);
col=mix(col,u_c1,(1.0-smoothstep(0.0018,0.0018+px,ad))*0.75);
float hub=1.0-smoothstep(0.007,0.007+px,d);
col=mix(col,u_c1,hub*0.8);
float rim=1.0-smoothstep(0.0,px,abs(d-R)-0.0008);
col=mix(col,u_c1,rim*0.25);
col+=(h(gl_FragCoord.xy)-0.5)*0.03;
gl_FragColor=vec4(col,1.0);
}",
