float dt=on*(1.0-smoothstep(sz,sz+px,d))*tw;
L=max(L,dt*(0.45+0.55*nr));
hot=max(hot,dt*nr);
}}
L*=lm;
hot*=lm;
float gl=exp(-dot(p-F,p-F)*260.0)*(0.85+0.15*sin(t*0.7));
